<script>
  import { onMount } from 'svelte';
  import { authStore, uiStore } from '../stores/index.js';
  import { auth } from '../providers/index.js';

  let showModal = false;
  let currentPassword = '';
  let newPassword = '';
  let confirmPassword = '';
  let isChanging = false;
  let errorMessage = '';

  let currentUser = null;

  authStore.subscribe(state => {
    currentUser = state.user;
  });

  function openModal() {
    showModal = true;
    resetForm();
  }

  function closeModal() {
    showModal = false;
    resetForm();
  }

  function resetForm() {
    currentPassword = '';
    newPassword = '';
    confirmPassword = '';
    errorMessage = '';
  }

  async function handleChangePassword() {
    errorMessage = '';

    // Validation
    if (!currentPassword || !newPassword || !confirmPassword) {
      errorMessage = '请填写所有字段';
      return;
    }

    if (newPassword.length < 8) {
      errorMessage = '新密码至少需要8个字符';
      return;
    }

    if (newPassword !== confirmPassword) {
      errorMessage = '两次输入的新密码不一致';
      return;
    }

    if (currentPassword === newPassword) {
      errorMessage = '新密码不能与当前密码相同';
      return;
    }

    isChanging = true;
    uiStore.showLoading('修改密码中...');

    try {
      // Re-authenticate first
      const email = currentUser.email;
      const { data: loginData, error: loginError } = await auth.signIn(email, currentPassword);
      
      if (loginError) {
        errorMessage = '当前密码错误';
        isChanging = false;
        uiStore.hideLoading();
        return;
      }

      // Change password using unified auth interface
      const { data, error: updateError } = await auth.updatePassword(newPassword, currentPassword);
      
      if (updateError) {
        throw updateError;
      }

      uiStore.hideLoading();
      uiStore.showNotification('密码修改成功，请使用新密码登录', 'success');
      closeModal();

      // Sign out to require re-login with new password
      setTimeout(async () => {
        await auth.signOut();
        window.location.reload();
      }, 2000);

    } catch (error) {
      console.error('Password change error:', error);
      errorMessage = error.message || '密码修改失败，请重试';
      uiStore.hideLoading();
    } finally {
      isChanging = false;
    }
  }
</script>

<div class="change-password-container">
  <button class="btn-change-password" on:click={openModal} title="修改密码">
    🔑 修改密码
  </button>

  {#if showModal}
    <div class="modal-overlay" on:click={closeModal} on:keydown={(e) => e.key === 'Escape' && closeModal()} role="button" tabindex="-1">
      <div class="modal" on:click|stopPropagation>
        <div class="modal-header">
          <h2>修改密码</h2>
          <button class="close-btn" on:click={closeModal}>×</button>
        </div>

        <div class="modal-body">
          <form on:submit|preventDefault={handleChangePassword}>
            <div class="form-group">
              <label for="current-password">当前密码 *</label>
              <input
                id="current-password"
                type="password"
                bind:value={currentPassword}
                placeholder="请输入当前密码"
                disabled={isChanging}
                required
              />
            </div>

            <div class="form-group">
              <label for="new-password">新密码 *</label>
              <input
                id="new-password"
                type="password"
                bind:value={newPassword}
                placeholder="至少8个字符"
                minlength="8"
                disabled={isChanging}
                required
              />
              <small>密码长度至少为8个字符</small>
            </div>

            <div class="form-group">
              <label for="confirm-password">确认新密码 *</label>
              <input
                id="confirm-password"
                type="password"
                bind:value={confirmPassword}
                placeholder="再次输入新密码"
                minlength="8"
                disabled={isChanging}
                required
              />
            </div>

            {#if errorMessage}
              <div class="error-message">
                {errorMessage}
              </div>
            {/if}

            <div class="modal-actions">
              <button type="submit" class="btn-primary" disabled={isChanging}>
                {isChanging ? '修改中...' : '确认修改'}
              </button>
              <button 
                type="button" 
                class="btn-secondary" 
                on:click={closeModal}
                disabled={isChanging}
              >
                取消
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  {/if}
</div>

