/**
 * 用户角色常量定义
 * 
 * 角色层级（从高到低）:
 * - super_admin: 超级管理员，最高权限
 * - admin: 管理员，可管理项目、分类和用户
 * - in_operator: 入库操作员，只能进行入库操作
 * - out_operator: 出库操作员，只能进行出库操作
 * - observer: 观察员，只能查看数据，无任何操作权限
 */

export const ROLES = {
    SUPER_ADMIN: 'super_admin',
    ADMIN: 'admin',
    IN_OPERATOR: 'in_operator',
    OUT_OPERATOR: 'out_operator',
    OBSERVER: 'observer'
};

// 角色显示名称
export const ROLE_LABELS = {
    [ROLES.SUPER_ADMIN]: '超级管理员',
    [ROLES.ADMIN]: '管理员',
    [ROLES.IN_OPERATOR]: '入库操作员',
    [ROLES.OUT_OPERATOR]: '出库操作员',
    [ROLES.OBSERVER]: '观察员'
};

// 角色描述
export const ROLE_DESCRIPTIONS = {
    [ROLES.SUPER_ADMIN]: '系统最高权限，可管理用户和所有数据',
    [ROLES.ADMIN]: '可创建项目、分类，管理所有材料数据',
    [ROLES.IN_OPERATOR]: '可录入和查看材料入库数据',
    [ROLES.OUT_OPERATOR]: '可录入和查看材料出库数据',
    [ROLES.OBSERVER]: '只能查看数据，无任何操作权限'
};

// 默认角色
export const DEFAULT_ROLE = ROLES.OBSERVER;

/**
 * 获取角色显示名称
 * @param {string} role - 角色标识
 * @returns {string} 角色显示名称
 */
export function getRoleLabel(role) {
    return ROLE_LABELS[role] || '用户';
}

/**
 * 检查是否有管理权限（super_admin 或 admin）
 * @param {string} role - 角色标识
 * @returns {boolean}
 */
export function isAdmin(role) {
    return role === ROLES.SUPER_ADMIN || role === ROLES.ADMIN;
}

/**
 * 检查是否可以进行入库操作
 * @param {string} role - 角色标识
 * @returns {boolean}
 */
export function canInbound(role) {
    return role === ROLES.SUPER_ADMIN ||
        role === ROLES.ADMIN ||
        role === ROLES.IN_OPERATOR;
}

/**
 * 检查是否可以进行出库操作
 * @param {string} role - 角色标识
 * @returns {boolean}
 */
export function canOutbound(role) {
    return role === ROLES.SUPER_ADMIN ||
        role === ROLES.ADMIN ||
        role === ROLES.OUT_OPERATOR;
}

/**
 * 检查是否可以创建项目/分类
 * @param {string} role - 角色标识
 * @returns {boolean}
 */
export function canCreateProject(role) {
    return role === ROLES.SUPER_ADMIN || role === ROLES.ADMIN;
}

/**
 * 检查是否可以管理用户
 * @param {string} role - 角色标识
 * @returns {boolean}
 */
export function canManageUsers(role) {
    return role === ROLES.SUPER_ADMIN || role === ROLES.ADMIN;
}

/**
 * 获取可由指定管理员创建的角色列表
 * @param {string} adminRole - 管理员角色
 * @returns {string[]} 可创建的角色列表
 */
export function getCreatableRoles(adminRole) {
    if (adminRole === ROLES.SUPER_ADMIN) {
        // 超级管理员可以创建所有角色（除了超级管理员自身）
        return [ROLES.ADMIN, ROLES.IN_OPERATOR, ROLES.OUT_OPERATOR, ROLES.OBSERVER];
    } else if (adminRole === ROLES.ADMIN) {
        // 管理员只能创建操作员和观察员
        return [ROLES.IN_OPERATOR, ROLES.OUT_OPERATOR, ROLES.OBSERVER];
    }
    return [];
}

/**
 * 获取可由指定管理员管理的角色列表
 * @param {string} adminRole - 管理员角色
 * @returns {string[]} 可管理的角色列表
 */
export function getManageableRoles(adminRole) {
    if (adminRole === ROLES.SUPER_ADMIN) {
        // 超级管理员可以管理所有角色（除了超级管理员自身）
        return [ROLES.ADMIN, ROLES.IN_OPERATOR, ROLES.OUT_OPERATOR, ROLES.OBSERVER];
    } else if (adminRole === ROLES.ADMIN) {
        // 管理员只能管理操作员和观察员
        return [ROLES.IN_OPERATOR, ROLES.OUT_OPERATOR, ROLES.OBSERVER];
    }
    return [];
}

/**
 * 检查是否可以编辑/删除入库记录
 * super_admin, admin, in_operator 可以编辑入库数据
 * @param {string} role - 角色标识
 * @returns {boolean}
 */
export function canEditInbound(role) {
    return role === ROLES.SUPER_ADMIN ||
        role === ROLES.ADMIN ||
        role === ROLES.IN_OPERATOR;
}

/**
 * 检查是否可以编辑/删除出库记录
 * super_admin, admin, out_operator 可以编辑出库数据
 * @param {string} role - 角色标识
 * @returns {boolean}
 */
export function canEditOutbound(role) {
    return role === ROLES.SUPER_ADMIN ||
        role === ROLES.ADMIN ||
        role === ROLES.OUT_OPERATOR;
}

/**
 * 检查是否可以编辑任意记录（admin级别）
 * @param {string} role - 角色标识
 * @returns {boolean}
 */
export function canEditAny(role) {
    return role === ROLES.SUPER_ADMIN || role === ROLES.ADMIN;
}
